head.script:
// 테스트 설명, 유효성 값 설정
//  ★ _3 : mergeOptionStr = byrestriccol / bycolupper (제약 병합). description 은 _1 과 동일.
scwin.tData = {
    "description" : "[gridView > M > mergeCells]<br/>GridView 컴포넌트의 mergeCells 속성을 설정합니다.",
    "validation" : [
        "mergeOptionStr 'byrestriccol' 설정 시 왼쪽 Column 이 병합된 범위 내에서 'bycol' 병합합니다.",
        "mergeOptionStr 'bycolupper' 설정 시 'byrestriccol' 방식이되 왼쪽 Column 이 아닌 Column 의 upperColumn 속성 값 기준으로 병합합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 검증 데이터 — byrestriccol / bycolupper 의 차이가 '계단식 병합' 으로 풍부하게 드러나도록 구성.
//  (왼쪽 col1 = 큰 그룹 → 오른쪽으로 갈수록 잘게 쪼개지는 계층)
//  계층형 cascade — 왼쪽 큰 그룹 → 오른쪽으로 갈수록 잘게 쪼개지는 세로 계층.
//  · col1 사업부  : 영업본부(0~2행) / 관리본부(3~5행)   (세로 2그룹 → bycolupper 기준 경계)
//  · col2 팀      : 1팀(0~1행) / 2팀(2행) / 3팀(3~5행)  (세로 3그룹 → byrestriccol 제한 경계)
//  · col3 평가등급 : 우수(0~4행) / 보통(5행)             (upperColumn=col1)
//        - byrestriccol → 왼쪽 col2(팀) 경계로 제한 → 우수가 1팀[0~1]/2팀[2]/3팀[3~4] 로 잘게 세로병합
//        - bycolupper   → col1(사업부) 기준 → 우수가 영업본부[0~2]/관리본부[3~4] 로 더 크게 세로병합
//  · col4 비고    : col3 과 동일값(우수/보통). upperColumn 미설정 → bycolupper 시 'bycol' 로 동작(연속 우수[0~4] 통째 세로병합)
scwin.MERGE_DATA = [
    { "col1": "영업본부", "col2": "1팀", "col3": "우수", "col4": "우수" },
    { "col1": "영업본부", "col2": "1팀", "col3": "우수", "col4": "우수" },
    { "col1": "영업본부", "col2": "2팀", "col3": "우수", "col4": "우수" },
    { "col1": "관리본부", "col2": "3팀", "col3": "우수", "col4": "우수" },
    { "col1": "관리본부", "col2": "3팀", "col3": "우수", "col4": "우수" },
    { "col1": "관리본부", "col2": "3팀", "col3": "보통", "col4": "보통" }
];



// comp 생성 : 계층형 그리드 1개를 동적 생성한다.
//  ★ mergeCells 속성은 생성 attribute 로 주지 않는다. (생성 후 mergeCells() 메소드로 적용)
//  ★ col3(평가등급) 에 upperColumn="col1"(사업부) 부여 → bycolupper 검증용.
scwin.comp_init = async function () {
    // 기존 target / label / DataList 정리 (동일 id 재생성 무시 방지)
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove(dlt_bind.id);
    }
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="사업부→팀→평가등급(upper=사업부) 계층. byrestriccol=평가등급(우수)이 팀 경계로 1팀[0~1]/2팀[2]/3팀[3~4] 제한 / bycolupper=사업부 기준이라 영업본부[0~2]/관리본부[3~4] 로 더 크게. par_mergeOptionStr 선택 후 mergeCells 버튼으로 적용"', '', 'label1');

    // 계층형 DataList 생성 (col1~col4) 후 병합 비교용 데이터 적재
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');
    dlt_bind.setJSON(scwin.MERGE_DATA, false);

    let cList = $c.gcm.createCList({
        dataList: "data:" + dlt_bind.id
    });

    // target 생성 (mergeCells 속성은 부여하지 않음 → 버튼 클릭 시 메소드로 적용)
    //  · col3(평가등급) 의 upperColumn="col1"(사업부) : bycolupper 일 때 기준 Column 을 팀(왼쪽) → 사업부(col1) 로 변경
    let grp_comp = document.querySelector('.tc_group_basic');
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' checkAllType="false" defaultCellHeight="38" id="" style="width:520px;height:300px;">';
    strTarget += '<w2:caption style="" id="caption1" value="mergeCells sample"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="110" style="" inputType="text" id="column1" value="사업부"></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="column2" value="팀"></w2:column>';
    strTarget += '<w2:column width="150" style="" inputType="text" id="column3" value="평가등급(upper=사업부)"></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="column4" value="비고"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="110" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="150" style="" inputType="text" id="col3" upperColumn="col1" value=""></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);
}



// mergeCells 실행 : par_mergeOptionStr 값(필수)으로 target1.mergeCells(mergeOptionStr) 호출
//  · options(선택) 파라미터는 _5(options 전용) 샘플에서 다루므로 여기서는 생략한다.
scwin.btn_mergeCells_onclick = function (e) {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    let mode = par_mergeOptionStr.getValue();

    target1.mergeCells(mode);

    bottom.setReturnValue("[옵션] mergeCells=" + target1.options.mergeCells + " / mergeOptionStr='" + mode + "'");

    scwin.printMergeState(bottom);
}



// 병합 상태 확인 : 각 Body td 의 rowSpan/colSpan 을 읽어 세로(⬇)/가로(➡)/블록(⬛) 병합 그룹을 출력
//  - td 셀렉터는 gid = target1.id 사용(e.target.id 는 버튼 id 라 사용 불가)
//  - 흡수되어 표시되지 않는 td 와 중복 키(고정/스크롤 영역 중복 id)는 제외
scwin.printMergeState = function (bottom) {
    let gid = target1.id;
    let tds = document.querySelectorAll("td[id*='" + gid + "_cell_']");
    if (tds.length === 0) {
        bottom.setReturnValue("body cell td 를 찾을 수 없습니다.");
        return;
    }

    let rowSpanCnt = 0;
    let colSpanCnt = 0;
    let descs = [];
    let seen = {};

    for (let i = 0; i < tds.length; i++) {
        let td = tds[i];
        if (getComputedStyle(td).display === 'none' || td.offsetParent === null) continue;
        let rs = td.rowSpan || 1;
        let cs = td.colSpan || 1;
        let m = td.id.match(/_cell_(\d+)_(\d+)/);
        if (!m) continue;
        let r = Number(m[1]), c = Number(m[2]);

        let key = r + "_" + c;
        if (seen[key]) continue;
        seen[key] = true;

        if (rs > 1 || cs > 1) {
            if (rs > 1) rowSpanCnt++;
            if (cs > 1) colSpanCnt++;
            let val = (td.textContent || "").trim();
            if (rs > 1 && cs === 1) {
                descs.push("⬇ col" + (c + 1) + " [행" + r + "~행" + (r + rs - 1) + "] 세로병합 = '" + val + "'");
            } else if (cs > 1 && rs === 1) {
                descs.push("➡ 행" + r + " [col" + (c + 1) + "~col" + (c + cs) + "] 가로병합 = '" + val + "'");
            } else {
                descs.push("⬛ [행" + r + "~행" + (r + rs - 1) + ", col" + (c + 1) + "~col" + (c + cs) + "] 블록병합(" + rs + "x" + cs + ") = '" + val + "'");
            }
        }
    }

    let modeName;
    if (rowSpanCnt === 0 && colSpanCnt === 0) modeName = "병합 없음";
    else if (rowSpanCnt > 0 && colSpanCnt === 0) modeName = "세로(rowSpan) 병합";
    else if (colSpanCnt > 0 && rowSpanCnt === 0) modeName = "가로(colSpan) 병합";
    else modeName = "혼합(블록) 병합";

    bottom.setReturnValue("판정 : " + modeName + " / 병합 그룹 " + descs.length + "개");
    if (descs.length === 0) {
        bottom.setReturnValue("병합된 셀 없음");
    } else {
        for (let d = 0; d < descs.length; d++) bottom.setReturnValue(descs[d]);
    }
}
